"""Training-side description-shift augmentation (TRAIN split images only; text generated by DeepSeek, text only).

Source: data/prep_v1/pool_natural.jsonl (RefCOCO/+/g train + gRefCOCO train records; every eval image already removed
by prep_v1) + COCO instances_train2014 (categories of the same images).
Tasks (cached per id in {out}/cache_*.jsonl, resumable):
  expr   : every box question (present AND absent) of the selected images -> zh translation + EN paraphrase;
           ~40% of present non-trivial ones also -> func (affordance rewrite keeping cues; EN/ZH) + vague (casual; EN/ZH)
  unique : per image, one non-person object whose category is unique in the image -> func_en/func_zh/generic_en/generic_zh;
           plus an absent category (category and supercategory not in the image) -> absent_func_en/zh, and an absent
           supercategory -> absent_generic_en/zh
Usage: python scripts/sprint_robust/gen_aug.py --out <dir> --n_images 6000
"""
import argparse, collections, json, os, random, sys, threading, time
from concurrent.futures import ThreadPoolExecutor

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from llm import chat  # noqa: E402

MAIN = "~/Developer/decision-vison"
ap = argparse.ArgumentParser()
ap.add_argument("--pool", default=f"{MAIN}/data/prep_v1/pool_natural.jsonl")
ap.add_argument("--ann", default=f"{MAIN}/data/ann")
ap.add_argument("--out", required=True)
ap.add_argument("--n_images", type=int, default=6000)
ap.add_argument("--func_frac", type=float, default=0.4)
ap.add_argument("--batch", type=int, default=25)
ap.add_argument("--workers", type=int, default=16)
ap.add_argument("--seed", type=int, default=0)
ap.add_argument("--only", default="", help="expr|unique")
a = ap.parse_args()
rng = random.Random(a.seed)
os.makedirs(a.out, exist_ok=True)

coco = json.load(open(f"{a.ann}/annotations/instances_train2014.json"))
cats = {c["id"]: c for c in coco["categories"]}
img_info = {im["id"]: im for im in coco["images"]}
img_anns = collections.defaultdict(list)
for an in coco["annotations"]:
    img_anns[an["image_id"]].append(an)

recs = [json.loads(l) for l in open(a.pool)]
by_img = collections.defaultdict(list)
for r in recs:
    by_img[r["image_id"]].append(r)
imgs = sorted(by_img)
rng.shuffle(imgs)
sel = imgs[: a.n_images]
json.dump(sel, open(f"{a.out}/selected_images.json", "w"))


def match_cat(iid, box):
    best, bi = None, 0.0
    for an in img_anns[iid]:
        x, y, w, h = an["bbox"]
        b = [x, y, x + w, y + h]
        ix = max(0, min(b[2], box[2]) - max(b[0], box[0])); iy = max(0, min(b[3], box[3]) - max(b[1], box[1]))
        u = (b[2] - b[0]) * (b[3] - b[1]) + (box[2] - box[0]) * (box[3] - box[1]) - ix * iy
        if u > 0 and ix * iy / u > bi:
            bi, best = ix * iy / u, an
    return cats[best["category_id"]]["name"] if best is not None and bi > 0.9 else None


def others(iid, excl_cat=None):
    W, H = img_info[iid]["width"], img_info[iid]["height"]
    return sorted({cats[an["category_id"]]["name"] for an in img_anns[iid] if an["area"] / (W * H) > 0.002})


expr_items, uniq_items = [], []
seen = set()
for iid in sel:
    oth = others(iid)
    for r in by_img[iid]:
        for q in r["questions"]:
            if q.get("type", "box") != "box":
                continue
            k = (iid, q["text"].lower())
            if k in seen:
                continue
            seen.add(k)
            it = dict(id=f"e{len(expr_items):06d}", image_id=iid, text=q["text"], present=bool(q["present"]))
            if q["present"]:
                it["cat"] = match_cat(iid, q["box"])
                it["need_func"] = bool(it["cat"]) and len(q["text"].split()) >= 2 and rng.random() < a.func_frac
                it["func_lang"] = rng.choice(["en", "zh"])
            expr_items.append(it)
    W, H = img_info[iid]["width"], img_info[iid]["height"]
    cc = collections.Counter(an["category_id"] for an in img_anns[iid])
    cand = [an for an in img_anns[iid] if cc[an["category_id"]] == 1 and not an["iscrowd"] and an["area"] / (W * H) >= 0.015
            and cats[an["category_id"]]["name"] != "person"]
    pc = set(cc); ps = {cats[c]["supercategory"] for c in pc}
    abs_c = [c["name"] for c in cats.values() if c["id"] not in pc and c["supercategory"] not in ps and c["name"] != "person"]
    abs_s = sorted({c["supercategory"] for c in cats.values()} - ps - {"outdoor", "indoor", "accessory", "person"})
    u = dict(id=f"u{len(uniq_items):06d}", image_id=iid, others=oth)
    if cand:
        an = rng.choice(cand); x, y, w, h = an["bbox"]
        u.update(cat=cats[an["category_id"]]["name"], supercat=cats[an["category_id"]]["supercategory"], box=[x, y, x + w, y + h])
    if abs_c:
        u["absent_cat"] = rng.choice(abs_c)
    if abs_s:
        u["absent_supercat"] = rng.choice(abs_s)
    uniq_items.append(u)
json.dump(dict(expr=expr_items, unique=uniq_items), open(f"{a.out}/items.json", "w"), ensure_ascii=False)
print("expr items", len(expr_items), "present", sum(i["present"] for i in expr_items),
      "need_func", sum(i.get("need_func", False) for i in expr_items), "unique items", len(uniq_items), flush=True)

SYS = ("You rewrite referring expressions for training a visual-grounding model on COCO photos. Return ONLY JSON "
       "{\"results\": [{\"id\": ..., <fields>}]} with one entry per input id. ")
TASK = dict(
    expr=("For each item `text` is an English referring expression (it may refer to an object in the photo, or, if "
          "present=false, to something that is NOT in the photo; keep its meaning exactly either way). Write:\n"
          " zh: natural colloquial Simplified Chinese translation, every attribute/location cue kept, nothing added; everyday "
          "words (guy->那个男的, kid->小孩, donut->甜甜圈).\n"
          " para: English paraphrase with the same meaning and different words (a synonym of the head noun if one exists, "
          "different syntax), keep every cue.\n"
          "Only if need_func=true also write (in language func_lang):\n"
          " func: the object's name (category `cat`) replaced by its function / affordance, cues kept ('red chair left' -> "
          "'the red thing to sit on at the left' / '左边红色的能坐的东西'); no category name, synonym or hypernym; for "
          "people describe role/activity instead.\n"
          " vague: a casual, vaguer version ('that one on the left', 'the guy in red', '左边那个') that still picks out the "
          "same object (age/gender words only if implied).\n"
          "Fields: id, zh, para, [func, vague]."),
    unique=("For each item (one photo; `others` = object categories in it):\n"
            " if `cat` is given (the only object of that category in the photo): func_en / func_zh = refer to it ONLY by its "
            "function / affordance (2-8 words, e.g. 'something to drink from' / '能喝水的东西'), never its name, a synonym or "
            "a hypernym, and not fitting any other category in `others`; generic_en / generic_zh = a vague supercategory-level "
            "noun ('the animal', 'something to eat', '那只动物', '吃的') that fits no other object in `others`. "
            "Use empty strings if impossible.\n"
            " if `absent_cat` is given (NOT in the photo): absent_func_en / absent_func_zh = a function / affordance query "
            "for it (without naming it) that no object in `others` could plausibly answer; empty if impossible.\n"
            " if `absent_supercat` is given (no object of that supercategory in the photo): absent_generic_en / "
            "absent_generic_zh = a generic noun phrase for that supercategory ('the animal', '车') that nothing in "
            "`others` fits; empty if impossible.\n"
            "Fields: id, func_en, func_zh, generic_en, generic_zh, absent_func_en, absent_func_zh, absent_generic_en, "
            "absent_generic_zh."),
)
PAY = dict(expr=lambda it: {k: it[k] for k in ("id", "text", "present", "cat", "need_func", "func_lang") if it.get(k) is not None},
           unique=lambda it: {k: it[k] for k in ("id", "cat", "supercat", "absent_cat", "absent_supercat", "others") if k in it})

for task, items in (("expr", expr_items), ("unique", uniq_items)):
    if a.only and task != a.only:
        continue
    fn = f"{a.out}/cache_{task}.jsonl"
    done = set()
    if os.path.exists(fn):
        done = {json.loads(l)["id"] for l in open(fn)}
    todo = [it for it in items if it["id"] not in done]
    bs = a.batch if task == "expr" else 15
    batches = [todo[i:i + bs] for i in range(0, len(todo), bs)]
    lock = threading.Lock(); st = collections.Counter(); t0 = time.time()
    fout = open(fn, "a")

    def work(b):
        ids = {it["id"] for it in b}
        for att in range(3):
            try:
                res = chat(SYS + TASK[task], json.dumps([PAY[task](it) for it in b], ensure_ascii=False))
                res = res.get("results", res) if isinstance(res, dict) else res
                got = [r for r in res if isinstance(r, dict) and r.get("id") in ids]
                if len(got) >= 0.8 * len(b) or att == 2:
                    with lock:
                        for r in got:
                            fout.write(json.dumps(r, ensure_ascii=False) + "\n")
                        fout.flush(); st["ok"] += len(got); st["miss"] += len(b) - len(got); st["batches"] += 1
                        if st["batches"] % 50 == 0:
                            print(task, dict(st), f"{time.time() - t0:.0f}s", flush=True)
                    return
            except Exception as e:
                err = str(e)[:100]
        with lock:
            st["failed"] += 1

    print(task, len(todo), "todo", len(batches), "batches", flush=True)
    with ThreadPoolExecutor(a.workers) as ex:
        list(ex.map(work, batches))
    print(task, "done", dict(st), f"{time.time() - t0:.0f}s", flush=True)
